import json,copy,pathlib,hashlib
P=pathlib.Path(__file__).resolve().parent;ROOT=P.parents[2];OLD=P.parent/'batch-01';old=json.loads((OLD/'cases_TC026_TC050.json').read_text());bank=copy.deepcopy(old);by={c['id']:c for c in bank['cases']}
def c(n):return by[f'TC-{n:03}']
def opt(n,l,**kw):c(n)['options'][ord(l)-65].update(kw)
def texts(n,ts):
 for o,t in zip(c(n)['options'],ts):o['text']=t
def explanation(n,l,text,tempt,when,q=None,pattern=None):
 o=c(n)['options'][ord(l)-65];o.update(explanation=text,whyNotBest='Наиболее обоснованно при данных условиях; границы применимости указаны ниже.' if o['isBest'] else text,whyTempting=tempt,whenItWouldBeBest=when)
 if q is not None:o['decisionQuality']=q
 if pattern:o.update(reasoningPattern=pattern,failurePattern=None if o['isBest'] else pattern)
# Exact blocker correction: an actual allocation, not a conditional hybrid that collapses to T&M.
for n in [29,30]:
 opt(n,'B',text='На старте закрепить две трети результата в пакетах с фиксированной ценой; оставшуюся треть вести по времени под общим cap.')
explanation(29,'B','Две трети уже формализованы и принимаются измеримо. Их фиксация без ценовой премии передаёт риск перерасхода поставщику; неопределённая треть остаётся гибкой.','Гибрид разделяет риск определённой и изменчивой частей.','Когда именно две трети объёма стабильны и фиксируются без неоправданной премии.',1)
explanation(30,'B','B обязывает зафиксировать две трети на старте, но ни один существенный пакет ещё нельзя надёжно определить. Возникают премия и платные изменения, которых избегает управляемый T&M.','Фиксация большей части обещает бюджетную определённость.','Если к старту две трети результата действительно имеют устойчивую приёмку.',.40)
c(29)['authorRationale']='B однозначно фиксирует две трети на старте: ровно эта доля стабильна по context. D оставляет риск перерасхода у заказчика без ценового выигрыша; A фиксирует ещё и неопределённую треть; C задерживает доступный старт.'
c(30)['authorRationale']='D против B: нет стабильных пакетов, а B требует фиксации двух третей именно на старте. D против A: весь объём изменчив, фиксированная цена включает премию и платные изменения. D против C: требования продолжают меняться, дополнительный месяц не устраняет причину и задерживает необходимый старт.'
# Score consistency only: preserve meaning and strongest.
opt(37,'D',decisionQuality=.40)
opt(48,'B',decisionQuality=.35)
# Whole-action counterfactual: payback really governs a final choice only under explicit conditions.
opt(42,'A',whenItWouldBeBest='Если ликвидность — обязательный решающий критерий, чистые годовые потоки подтверждены как постоянные, а допустимые альтернативы равноценны по риску и долгосрочному эффекту. Тогда выбор по рассчитанной окупаемости покрывает весь вариант.')
# Four Senior implementations: preserve frozen subject, domain, pattern, level and decision direction.
c(36).update(context='Вы готовите выход сервиса ремонта в новый регион: база и найм требуют 18 млн рублей, часть контрактов невозвратна. Главная неизвестность — спрос по полной цене. Предварительные заявки пришли по скидке от сотрудников двух компаний; такой канал нельзя масштабировать. За неделю и 120 тыс. можно провести fake-door test по полной цене с честной пометкой будущего запуска, разделив обычную платную аудиторию и прежний льготный канал. Порог достаточного спроса рассчитан для платного привлечения. Покупка базы не повышает точность этой проверки. Даже успешный тест не проверяет качество исполнения; доступный состав мастеров зависит от отдельного ещё не принятого обязательства подрядчика. Резервирование базы можно отложить на неделю без удорожания. Нужно определить, какое знание покупать сейчас и к каким обязательствам оно даст основание.',question='Как построить первый шаг и последующее инвестиционное решение?',decisiveFacts=['Предварительный спрос получен по скидке через немасштабируемый канал.','Дешёвый тест может отдельно измерить спрос по полной цене из платного канала.','Положительный спрос не доказывает исполнение; его обеспечение зависит от отдельного обязательства.'],keyInsight='Дешёвое evidence ценно только для той неопределённости и тех условий, которые оно действительно проверяет.',mentalModel='Разделяйте связанные допущения и пределы доказательства. Сначала проверяйте решающую неизвестность в целевых условиях, а последующие обязательства привязывайте к ещё не проверенным зависимостям.',sourceTopicExplanation='§5.6 требует называть отдельные неизвестные, сравнивать цену информации с ценой ошибки и строить этапы с точками выхода. Реестр допущений и планы проверки не позволяют выдать частичное знание за готовность всей программы.',authorRationale='Senior: нужно выявить смещение имеющегося evidence, отделить спрос от способности исполнить и спроектировать последовательность условных обязательств. Недостаточно выбрать самый дешёвый тест: его аудитория и допустимый вывод определяют риск последующего коммита.')
texts(36,[
'Открыть малую базу для обычной аудитории и проверить полный цикл заказа; решение о региональной сети отложить до результата пилота.',
'Проверить платный спрос отдельно от льготного; следующий этап ограничить проверкой исполнения, а не сразу контрактом на полный запуск.',
'Сначала уточнить мотивы заявителей в интервью и проверить приемлемость цены; вопрос аренды оставить открытым до поведенческих данных.',
'Измерить общий спрос обоих каналов и сверить его с порогом; при успехе подписать базу, а готовность подрядчика проверять параллельно.'])
explanation(36,'A','Пилот даёт знания и об исполнении, но требует частично необратимых вложений до проверки спроса. Для выделенной первой неизвестности база точности не добавляет.','Полный цикл выявляет проблемы, которых не видно в заявке.','Если валидность спроса зависит от реального обслуживания и дешёвое предложение существенно искажает поведение.',.72)
explanation(36,'B','Раздельное измерение исключает перенос льготного спроса на платный канал. Ограничение следующего этапа не превращает спрос в недоказанную готовность мастеров и защищает от преждевременной аренды.','Можно получить нужное знание без потери доступного окна запуска.','Когда дешёвая проверка валидна для спроса, но остальные зависимости запуска ещё не подтверждены.',1)
explanation(36,'C','Коммит отложен корректно, однако мотивы льготных заявителей не отвечают на уже сформулированный вопрос о поведении платной аудитории; прямой тест доступен сейчас.','Интервью могут объяснить причины интереса и отказы.','Когда предложение или причины поведения ещё неясны и интервью нужны для проектирования последующей поведенческой проверки; аренда остаётся отложенной.',.60, 'interviews-before-available-behavioral-test')
explanation(36,'D','Общий результат смешает немасштабируемый льготный канал с платным. Даже корректный спрос не подтверждает способность подрядчика выполнить заказы, поэтому аренда остаётся преждевременной.','Агрегат проще сравнить с бизнес-порогом, параллельные действия ускоряют подготовку.','Если аудитория соответствует модели привлечения и исполнение уже подтверждено до принятия обязательств.',.35,'partial-evidence-as-full-readiness')
c(38).update(context='Вы ведёте необходимое изменение REST API расписаний для семи независимых клиентов; два не могут обещать дату из-за внешнего согласования. Две версии API доступны на шесть недель. Новый статус «место назначено» появляется до оплаты, тогда как старое «подтверждено» разрешает клиентам выдавать билет только после оплаты. Инженеры предлагают назвать новый статус старым в ответе v1: формально поля совпадут. Событие оплаты сохраняется, поэтому старый смысл можно воспроизвести в сервисе, но проверка контрактов сейчас сравнивает только форму JSON. Некоторые клиенты обращаются редко: отсутствие их запросов за день не доказывает миграцию. Владельцы известны, метрика версий есть; отменить новую функцию нельзя.',question='Какой план перехода учитывает и совместимость, и завершение миграции?',decisiveFacts=['Одинаковая форма JSON скрывает разный момент разрешения выдачи билета.','Событие оплаты позволяет сохранить старую семантику внутри сервиса.','Редкие обращения не позволяют завершать миграцию по одному тихому дню.'],keyInsight='Наличие двух endpoint не гарантирует сохранения смысла контракта и не доказывает готовность удалить старый.',mentalModel='Проверяйте совместимость через действия потребителя, а завершение перехода — через доказанную готовность каждого клиента. Техническое сосуществование и критерий выхода нужно проектировать вместе.',sourceTopicExplanation='§10.1 рассматривает версионирование API как межкомандную зависимость и описывает контрактные проверки совместимости до релиза. Поддержка старой версии должна сохранять поведение клиента, а план миграции — учитывать независимость его выпуска.',authorRationale='Senior: требуется обнаружить семантическую несовместимость за одинаковой схемой, изменить механизм проверки контракта и выбрать критерий выхода при неполной телеметрии редких клиентов. Это больше, чем календарно включить готовую поддержку двух версий.')
texts(38,[
'Сохранить в v1 оплату как условие подтверждения; проверить действия клиентов и закрывать окно по их переходу, сверяя телеметрию.',
'Согласовать общую дату через шесть недель; до неё сохранить прежнюю логику целиком, затем переключить всех после общего регресса.',
'Поддержать обе версии с переименованием статуса для v1; при ошибках выдачи билета откатывать новый код и продлевать окно миграции.',
'Сохранить прежний смысл v1 и проверить оплату в тестах; удалить v1 после суток без старых запросов, уведомив владельцев заранее.'])
explanation(38,'A','Событие оплаты сохраняет поведенческий контракт v1, а тесты действий ловят то, что не ловит форма JSON. Подтверждение перехода владельцами вместе с телеметрией учитывает редкие обращения.','Можно выпустить новую функцию без поломки старых клиентов и бесконечной поддержки.','Когда старую семантику можно сохранить, но клиенты мигрируют независимо и не все постоянно активны.',1)
explanation(38,'B','Общий регресс полезен, но два клиента не контролируют дату внешнего согласования. Жёсткая общая точка переносит эту неопределённость на всю необходимую функцию.','Один cutover сокращает время поддержки двух контрактов.','Если все клиенты гарантируют готовность к общей дате и переход проверен.',.55)
explanation(38,'C','Переименование заставит старых клиентов выдавать билет до оплаты. Откат после инцидента не заменяет доступную до релиза проверку поведения.','Сохранение формы JSON кажется совместимостью без дополнительной логики.','Если новое значение семантически эквивалентно старому для всех потребителей.',.30,'syntactic-compatibility-only')
explanation(38,'D','Семантика сохранена, но тихие сутки не означают переход редких клиентов. Удаление может сломать их следующее обращение, хотя уведомление уже отправлено.','Нулевой трафик даёт простой измеримый критерий окончания окна.','Если все потребители гарантированно обращаются в этом окне и отсутствие старых запросов действительно подтверждает переход.',.75,'silence-as-migration-proof')
c(43).update(context='Вы владеете сервисом подбора поездок. Error budget пользовательского подбора почти исчерпан; прогноз пересёк trigger паузы feature-релизов. Продукт просит малорисковую подсказку с быстрым выключением флагом ради кампании. Исключения policy — только security/regulatory. Подсказка выпускается отдельным pipeline и добавляет запросы в общую очередь подбора: локальный HTTP SLI зелёный, но просроченные результаты очереди уже расходуют общий бюджет. Сейчас каждый pipeline решает go/no-go по своей локальной панели. Отдельный выпуск справочника не использует очередь и не влияет на подбор. Команды спорят, распространяется ли пауза на подсказку. Вы вправе согласовать единый технический критерий применения действующей policy, но не расширять исключения.',question='Как разрешить запрос и устранить повторение такого спора?',decisiveFacts=['Подсказка относится к тому же пользовательскому пути через общую очередь, несмотря на зелёный локальный HTTP SLI.','Go/no-go принимается раздельно по компонентам, бюджет — общий для результата подбора.','Справочник не влияет на этот путь; расширять исключения нельзя.'],keyInsight='Политика общего бюджета не работает, если её исполняют по несопоставимым локальным сигналам.',mentalModel='Свяжите границы решения о выпуске с пользовательским SLI и зависимостями. Устраните механизм обхода общего ограничения, не замораживая независимую поставку.',sourceTopicExplanation='§10.5 требует измерять SLI по завершению пользовательского сценария, а не только успешному ответу компонента, и связывает error budget с темпом feature-релизов. Это позволяет применить действующее правило к общему пути без нового бизнес-исключения.',authorRationale='Senior: нужно объяснить расхождение локального и пользовательского сигналов, определить область действия общего ограничения и изменить механизм go/no-go нескольких pipeline. Простое «отказать по policy» не закрывает повторяемую причину и риск избыточной заморозки независимых релизов.')
texts(43,[
'Привязать go/no-go связанных pipeline к общему SLI и поставить подсказку на паузу; независимый справочник выпускать по его проверкам.',
'Выпустить подсказку малой волной по зелёному HTTP SLI; наблюдать очередь, а при ускорении расхода бюджета выключить функцию флагом.',
'Остановить все feature-pipeline сервиса до восстановления бюджета; единый полный freeze использовать вместо согласования зависимостей.',
'Отказать в текущем исключении для подсказки; оставить локальные go/no-go, а следующие спорные запросы решать на встречах владельцев.'])
explanation(43,'A','Общая очередь связывает подсказку с исчерпываемым пользовательским бюджетом. Единый критерий закрывает локальную лазейку, а независимый справочник не платит за чужой риск.','Один смысл policy сохраняется при нескольких путях поставки.','Когда локальные показатели расходятся с общим SLI и можно выделить затрагивающие его компоненты.',1)
explanation(43,'B','Зелёный HTTP не учитывает уже просроченный результат очереди. Малый rollout добавляет нагрузку в тот же путь после trigger и не является разрешённым исключением.','Флаг и малая волна ограничивают ущерб отдельного изменения.','Если релиз не затрагивает путь с исчерпанным бюджетом либо подпадает под разрешённое исключение.',.40)
explanation(43,'C','Freeze остановит обход, но заблокирует и справочник, чья независимость явно установлена. Цена ограничения растёт без выигрыша в защищаемом SLI.','Единая остановка проста и исключает спор о границах.','Если все pipeline влияют на один бюджет или быстро доказать независимость невозможно.',.60,'overbroad-freeze')
explanation(43,'D','Текущий ответ верен, но разные локальные сигналы сохраняют причину следующего конфликта. Доступный технический механизм опять подменяется ручной встречей.','Можно быстро соблюсти policy без изменения процессов поставки.','Если расхождение единично и критерии применения в pipeline уже согласованы.',.80,'manual-policy-application')
c(45).update(context='Вы ведёте межкомандный запуск. Платформа будет готова к концу дня 6; ускорить её нельзя. Затем планом предусмотрены 8 дней клиентской работы и 2 дня сквозной проверки. Три из восьми дней — независимые локальные экраны и аналитика с фиксированным интерфейсом; их можно выполнить до платформы без новых людей и расходов. Остальные пять требуют реальной интеграции. Но сквозная проверка также ждёт обязательный набор мигрированных данных: другая команда выдаст его только к концу дня 13. Оба условия нужны одновременно; длительность финальной проверки не сокращается. Спонсор просит использовать параллельность и назвать достижимую дату вместо обещания полного выигрыша трёх дней.',question='Какой план и прогноз следует согласовать?',decisiveFacts=['Три дня безопасно отделимы; платформа на дне 6 и пять дней интеграции остаются обязательными.','Сквозная проверка ждёт также данные до конца дня 13.','Финальная проверка занимает два дня после готовности обеих ветвей.'],keyInsight='После сокращения одной ветви критический путь может перейти на другую; выигрыш локальной работы не равен выигрышу даты проекта.',mentalModel='Развязывайте доступные зависимости, затем пересчитывайте все пути до общей вехи. Сохраняйте обязательные проверки и явно отделяйте локальную экономию от сокращения общего срока.',sourceTopicExplanation='§2.4 рассматривает изменение критического пути, несколько сходящихся цепочек и пересмотр дискреционных зависимостей. После безопасного распараллеливания нужно заново найти путь, ограничивающий общий финиш.',authorRationale='Senior: требуется перестроить зависимость и учесть вторичный эффект — после ускорения клиентской ветви ограничителем становятся данные другой команды. Кандидат должен согласовать обе ветви с общей проверкой и не перенести три дня локальной экономии в ложное внешнее обещание.')
texts(45,[
'Сохранить последовательность восьми дней после платформы и завершить проверку в день 16; готовность данных контролировать отдельно.',
'Вынести независимые три дня вперёд; пересчитать обе ветви к общей проверке и согласовать финиш на конец дня 15 без новых ресурсов.',
'Начать все восемь дней до платформы на тестовых данных; назначить день 13 для завершения, оставив последние два дня на сквозную проверку.',
'Вынести три дня вперёд и завершить интеграцию к дню 11; обещать финиш на день 13, отведя следующие два дня на сквозную проверку.'])
explanation(45,'A','Данные будут готовы раньше клиентской ветви, но три независимых дня всё равно простаивают. Их перенос не стоит дополнительных ресурсов и сокращает финиш хотя бы на день.','Сохранение последовательности уменьшает число изменений плана.','Если независимые работы нельзя безопасно перенести или цена переноса превышает выигрыш.',.65)
explanation(45,'B','Клиентская ветвь готова на дне 11, но общая проверка стартует только после данных на дне 13. Два дня проверки дают финиш 15, а не 13: критический путь сменился.','План использует безопасную параллельность и сохраняет выполнимое обязательство.','Когда независимый фрагмент можно перенести, а общая веха ждёт несколько обязательных ветвей.',1)
explanation(45,'C','Пять дней требуют реальной платформы; тестовые данные не снимают эту зависимость. Кроме того, обязательные мигрированные данные не готовы к предполагаемому старту проверки.','Максимальная параллельность обещает самый ранний результат.','Если вся работа отделена проверенным контрактом и обе предпосылки сквозной проверки готовы раньше.',.30)
explanation(45,'D','Перенос трёх дней корректен, но проверка не может идти с дня 11: данные появятся лишь к концу 13. Вариант принимает локальную экономию за общий выигрыш.','Дата получается быстрым вычитанием трёх дней из прежнего срока.','Если клиентская ветвь остаётся единственным ограничителем и остальные предпосылки готовы к дню 11.',.55,'local-gain-as-project-gain')
# Style normalization on only the named surface group. Keep strategy meaning and ordering.
style={
35:['Приостановить интеграцию на две недели и уточнить спорные пункты; после публикации собрать план разработки, проверки и запуска.', 'Реализовать всю текущую спецификацию через отдельный адаптер; на ежедневном обзоре учитывать ответы оператора, стоимость и сроки переделок.', 'Сразу выбрать ручной расчёт на первый период; стабильную часть завершить к дате, а спорную разработку отложить до спецификации.', 'Продолжить стабильную часть с изоляцией спорного; уточнить её сегодня и назначить момент перехода на резервный расчёт.'],
39:['Укрепить роли координации и контроль framework; на общем совете разбирать отклонения, решения и ответственность команд.', 'Отменить общие роли и планирование; оставить интеграционные проверки, а договорённости с платформой передать командам.', 'Сократить церемонии и ограничить время согласований; сохранить роли до обзора, измеряя ожидание платформы и затраты времени.', 'Пересобрать роли и границы по карте продуктовых и платформенных зависимостей; оставить общую координацию там, где она сокращает ожидание.'],
40:['До планирования лично согласовывать спорные инициативы с тремя сторонами; сохранить их нынешние права, KPI и порядок разрешения споров.', 'Закрепить критерии выбора и владельца решения для каждого класса конфликтов; включить границы veto в регулярное планирование.', 'Передавать спонсору каждый спор с оценкой последствий; CPO, CTO и compliance оставить прежние права и цели.', 'Разделить capacity поровну между тремя направлениями; дать им автономию внутри долей, а общие вопросы обсуждать ежеквартально.'],
41:['Собирать вопросы на ежедневное окно решений; самому согласовывать сроки, ресурсы и приоритеты вместо отдельных прерываний.', 'Обучить менеджеров принятию решений и оставить личный контроль; после курса оценить самостоятельность, ошибки и готовность делегировать.', 'Договориться о результатах и границах самостоятельности менеджеров; вместо участия в рабочих встречах проверять результаты и эскалации.', 'Назначить старшего менеджера для предварительной проверки вопросов; себе оставить итоговое согласование, контроль и право пересмотра.'],
42:['Пересчитать первый год в срок окупаемости по экономии 2,5 млн; выбрать проект с более быстрым возвратом первоначальных инвестиций.', 'Сохранить годовой ROI и дополнить его качественными выгодами; сравнить предложения по стратегии, эффекту и этому показателю.', 'Умножить экономию первого года на три и рассчитать общий ROI; после предварительного одобрения уточнить поддержку, лицензии и расходы.', 'Сопоставить трёхлетние потоки обоих проектов при ставке финансов; на этой основе оценить ROI вместе с окупаемостью и NPV.'],
44:['Начать часовой откат и предупредить бизнес о паузе; после восстановления разобрать ошибки, их причины и условия повторного выпуска.', 'Сохранить релиз до суточного отчёта; после выравнивания трафика проверить рост ошибок, устойчивость тренда и влияние на операции.', 'За 15 минут локализовать ошибки по версии и региону с разбивкой endpoint; выбрать меру для сегмента и сохранить аварийный trigger.', 'Остановить расширение и ещё полчаса собирать общий сигнал; выбрать откат по тренду, величине отклонения и его устойчивости.'],
46:['Назначить владельцев трёх рисков и вести единый реестр; еженедельно обновлять влияние, вероятность и ожидаемые сроки ответа.', 'Начать с месячного исследования модуля; по его итогам уточнить партнёра, решение регулятора и общий план программы.', 'Начать по вероятному режиму с исследованием параллельно; по мере уточнений пересматривать сроки, допущения и ход работ.', 'Выяснить окно сегодня и после оценки запустить исследование до коммита; для будущего решения регулятора подготовить планы с датой переключения.'],
48:['Перевести команды на общий release train и изменить таблицу в одном окне; до конца перехода синхронизировать сборки, проверки и откаты.', 'Дождаться полной готовности сервиса на старой схеме; затем одним окном перевести читателей, сменить формат и удалить старое поле.', 'Проверить обоих читателей на совместимом промежуточном формате; переключать команды поэтапно и удалить старое поле после перехода.', 'Поставить преобразователь перед монолитом и сразу сменить формат; в окне миграции проверять чтение, согласованность и ошибки.'],
49:['Передать CTO согласование технических действий во всех крупных инцидентах; остальных директоров собирать отдельно, не отвлекая инженеров.', 'Обучить директоров коммуникации и обновить runbook; на первом созвоне каждого инцидента определять роли, полномочия и каналы.', 'Собирать поручения у одного секретаря; инженерам передавать общий список с приоритетами, а исполнение отмечать в журнале.', 'Закрепить мандаты IC и лидов технической работы и коммуникации; подготовить участников и направлять руководство через эти роли.'],
50:['Начать с 5% заказов и усиленного дежурства; после недели работы добавить сквозную корреляцию, уточнив дальнейший объём раскатки.', 'Провести trace ID через очередь до downstream и проверить локализацию; результат диагностического сценария включить в решение о запуске.', 'Повысить детализацию локальных логов и собрать владельцев на запуск; события связывать по времени, источнику и наблюдаемому эффекту.', 'Отложить выпуск до унификации мониторинга всех сервисов; пересмотреть панели, хранение логов и правила алертов общей цепочки.']}
for n,ts in style.items():texts(n,ts)
